div.script:
const fileInput = document.getElementById("file");
const openButton = document.getElementById("open");
const status = document.getElementById("status");

openButton.addEventListener("click", async () => {
  const file = fileInput.files[0];

  if (!file) {
    status.textContent = "Choose an HTML file first.";
    return;
  }

  try {
    const html = await file.text();

    // Open a blank tab, then replace its document with the
    // selected HTML. No external server is required.
    const win = window.open("about:blank", "_blank");

    if (!win) {
      status.textContent =
        "The browser blocked the new tab. Allow pop-ups for this file and try again.";
      return;
    }

    win.document.open();
    win.document.write(html);
    win.document.close();

    status.textContent = "Opened " + file.name;
  } catch (err) {
    status.textContent = "Could not open the file: " + err.message;
  }
});
